        nn.init.trunc_normal_(self.conv.weight, std=0.02)
        nn.init.zeros_(self.conv.bias)

    def forward(self, h):
        start = (h.shape[-1] - OUT_LEN) // 2
        return self.conv(h)[..., start:start + OUT_LEN]


class CAPY(nn.Module):
    """Baseline Y-net. In training mode it also runs reverse-complement copies of the first half of the batch (Siamese RC
    pairs) and returns them as rc_profile / rc_counts (in RC coordinates) for the objective's consistency terms."""

    def __init__(self):
        super().__init__()
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = YCountHead()
        self.decoder = Decoder()
        self.profile_head = ProfileHead()
        self.progress, self.epoch = 0.0, 0

    def _core(self, x):
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        counts = self.count_head(z)
        profile = self.profile_head(self.decoder(z, skips))
        return profile, counts

    def forward(self, x):
        if self.training and x.shape[0] >= 2:
            b = x.shape[0]
            h = b // 2
            xr = x[:h].flip(1).flip(2)          # ACGT -> TGCA (complement) and reversed
            profile, counts = self._core(torch.cat([x, xr], 0))
            return {"profile": profile[:b], "counts": counts[:b],
                    "rc_profile": profile[b:], "rc_counts": counts[b:]}
        profile, counts = self._core(x)
        return {"profile": profile, "counts": counts}


def build_model():
    return CAPY()

