class StandardizedConv1d(nn.Conv1d):
    """CAPYBARA's weight-standardised 'same' convolution."""

    def __init__(self, cin, cout, k, dilation=1):
        super().__init__(cin, cout, k, padding=0, dilation=dilation, bias=True)
        self.scale = nn.Parameter(torch.ones(cout, 1, 1))

    def forward(self, x):
        w = self.weight
        var = w.var(dim=(1, 2), unbiased=False, keepdim=True)
        fan_in = self.in_channels * self.kernel_size[0]
        w = (w - w.mean(dim=(1, 2), keepdim=True)) * torch.rsqrt(torch.clamp(var * fan_in, min=1e-4)) * self.scale
        total = self.dilation[0] * (self.kernel_size[0] - 1)
        x = F.pad(x, (total // 2, total - total // 2))
        return F.conv1d(x, w.to(x.dtype), self.bias.to(x.dtype), dilation=self.dilation)


class ConvBlock(nn.Module):
    """CAPYBARA pre-activation conv block: norm -> GELU -> dropout -> conv."""

    def __init__(self, channels, k, dropout=0.1):
        super().__init__()
        self.norm, self.act, self.drop = group_norm(channels), nn.GELU(), nn.Dropout(dropout)
        self.conv = StandardizedConv1d(channels, channels, k)

    def forward(self, x):
        return self.conv(self.drop(self.act(self.norm(x))))


class HybridAttentionUnit(nn.Module):
    """CAPYBARA HybridAttentionUnit: a residual pair of conv blocks, then pre-norm multi-head self-attention and an MLP."""

    def __init__(self, channels, k=5, heads=4, mlp_ratio=2.0, dropout=0.1, attn_dropout=0.1):
        super().__init__()
        self.conv1, self.conv2 = ConvBlock(channels, k, dropout), ConvBlock(channels, k, dropout)
        self.attn_norm = group_norm(channels)
        self.attn = nn.MultiheadAttention(channels, heads, dropout=attn_dropout, batch_first=True)
        hidden = max(channels, int(channels * mlp_ratio))
        self.ffn_norm = group_norm(channels)
        self.ffn = nn.Sequential(nn.Linear(channels, hidden), nn.GELU(), nn.Dropout(dropout), nn.Linear(hidden, channels),
                                 nn.Dropout(dropout))

    def forward(self, x):
        x = x + self.conv2(self.conv1(x))
        y = self.attn_norm(x).transpose(1, 2)
        x = x + self.attn(y, y, y, need_weights=False)[0].transpose(1, 2)
        return x + self.ffn(self.ffn_norm(x).transpose(1, 2)).transpose(1, 2)


class Encoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES):
        super().__init__()
        self.stem = nn.Conv1d(4, width, 21, padding=10)
        nn.init.trunc_normal_(self.stem.weight, std=0.02)
        nn.init.zeros_(self.stem.bias)
        self.blocks = nn.ModuleList([CheriBlock(width) for _ in range(n_stages)])

    def forward(self, x):
        x = F.gelu(self.stem(x), approximate="tanh")
        skips = []
        for block in self.blocks:
            x = block(x)
            skips.append(x)
            x = F.avg_pool1d(x, 2, ceil_mode=True)
        return x, skips


class Bottleneck(nn.Module):
    def __init__(self, width=WIDTH, depth=3):
        super().__init__()
        self.cheri = CheriBlock(width)
        self.units = nn.Sequential(*[HybridAttentionUnit(width) for _ in range(depth)])

    def forward(self, x):
        return self.units(self.cheri(x))


class YCountHead(nn.Module):
    """CAPYBARA YCountHead: conv [128, 64] (kernel 5, GroupNorm, GELU, dropout, max-pool 2), adaptive average pool to 4
    bins, MLP [64] with LayerNorm, then one output: ln(total counts + 1)."""

    def __init__(self, width=WIDTH, convs=(128, 64), mlp=(64,), k=5, bins=4, dropout=0.1):
        super().__init__()
        layers, c = [], width
        for h in convs:
            layers += [nn.Conv1d(c, h, k, padding=k // 2, bias=False), group_norm(h), nn.GELU(), nn.Dropout(dropout),
                       nn.MaxPool1d(2, ceil_mode=True)]
            c = h
        self.convs, self.bins = nn.Sequential(*layers), bins
        layers, d = [], c * bins
        for h in mlp:
            layers += [nn.Linear(d, h), nn.LayerNorm(h), nn.GELU(), nn.Dropout(dropout)]
            d = h
        self.mlp = nn.Sequential(*layers, nn.Linear(d, 1))

    def forward(self, z):
        return self.mlp(F.adaptive_avg_pool1d(self.convs(z), self.bins).flatten(1))


class GatedSkipFusion(nn.Module):
    """up + 2*sigmoid(W[up; skip])*skip, W a zero-initialised kernel-1 conv, so the gate starts at 1."""

    def __init__(self, width=WIDTH):
        super().__init__()
        self.gate = nn.Conv1d(2 * width, width, 1)
        nn.init.zeros_(self.gate.weight)
        nn.init.zeros_(self.gate.bias)

    def forward(self, up, skip):
        return up + 2 * torch.sigmoid(self.gate(torch.cat([up, skip], 1))) * skip


class Decoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES, blocks_per_stage=2):
        super().__init__()
        self.fuse = nn.ModuleList([GatedSkipFusion(width) for _ in range(n_stages)])
        self.blocks = nn.ModuleList([nn.Sequential(*[CheriBlock(width) for _ in range(blocks_per_stage)])
                                     for _ in range(n_stages)])

    def forward(self, z, skips):
        x = z
        for fuse, blocks, skip in zip(self.fuse, self.blocks, reversed(skips)):
            x = F.interpolate(x, size=skip.shape[-1], mode="nearest")
            x = blocks(fuse(x, skip))
        return x


class ProfileHead(nn.Module):
    """Cherimoya's profile head: one kernel-75 conv, then the central 1,000 positions."""

    def __init__(self, width=WIDTH, k=75):
        super().__init__()
        self.conv = nn.Conv1d(width, 1, k, padding=k // 2)
        nn.init.trunc_normal_(self.conv.weight, std=0.02)
        nn.init.zeros_(self.conv.bias)

    def forward(self, h):
        start = (h.shape[-1] - OUT_LEN) // 2
        return self.conv(h)[..., start:start + OUT_LEN]


class CAPY(nn.Module):
    """CAPY baseline Y-net with Siamese reverse-complement pair training: in training mode the first half of the batch is
    reverse-complemented (one-hot ACGT: flipping channels gives the complement) and run alongside; the RC outputs are
    flipped back to forward-strand coordinates and returned as rc_profile / rc_counts for the objective."""

    def __init__(self):
        super().__init__()
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = YCountHead()
        self.decoder = Decoder()
        self.profile_head = ProfileHead()
        self.progress, self.epoch = 0.0, 0

    def _run(self, x):
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        counts = self.count_head(z)
        profile = self.profile_head(self.decoder(z, skips))
        return profile, counts

    def forward(self, x):
        if self.training and x.shape[0] >= 2:
            b = x.shape[0]
            h = b // 2
            xx = torch.cat([x, x[:h].flip(1, 2)], 0)
            profile, counts = self._run(xx)
            return {"profile": profile[:b], "counts": counts[:b],
                    "rc_profile": profile[b:].flip(-1), "rc_counts": counts[b:]}
        profile, counts = self._run(x)
        return {"profile": profile, "counts": counts}


def build_model():
    return CAPY()

# --- block: objective ---
class Objective(nn.Module):
    """Cherimoya's training loss (profile MNLL + count MSE on ln(total + 1), Kendall-Gal learned weights 1 / (2 s^2) with
    regulariser (log s)^2, frozen after the first epoch where |grad s0| < 1), plus Siamese reverse-complement pairs: the RC
    copies (outputs already re-aligned to the forward strand) are supervised on the same targets, and tied to the forward
    outputs by a symmetric profile KL (weight 50) and a squared log-count consistency (weight 0.5)."""

    KL_WEIGHT = 50.0
    COUNT_CONS_WEIGHT = 0.5

    def __init__(self):
        super().__init__()
        self.s0 = nn.Parameter(torch.ones(1))
        self.s1 = nn.Parameter(torch.ones(1))

    def forward(self, out, y, is_peak, net):
        profile = out["profile"]
        counts = out["counts"].float()
        target = log_total(y)
        lp = mnll(profile, y)
        lc = (target - counts) ** 2
        sym_kl = torch.zeros((), device=counts.device)
        cons = torch.zeros((), device=counts.device)
        if "rc_profile" in out and out["rc_profile"].shape[0] > 0:
            rp = out["rc_profile"]
            rc = out["rc_counts"].float()
            h = rp.shape[0]
            lp = torch.cat([lp, mnll(rp, y[:h])], 0)
            lc = torch.cat([lc, (target[:h] - rc) ** 2], 0)
            logp = torch.log_softmax(profile[:h].float(), dim=-1)
            logq = torch.log_softmax(rp.float(), dim=-1)
            sym_kl = ((logp.exp() - logq.exp()) * (logp - logq)).sum(-1).mean()
            cons = ((counts[:h] - rc) ** 2).mean()
        profile_loss = lp.mean()
        count_loss = lc.mean()
        loss = profile_loss / (2 * self.s0 ** 2) + count_loss / (2 * self.s1 ** 2)
        if self.s0.requires_grad:
            loss = loss + torch.log(self.s0) ** 2 + torch.log(self.s1) ** 2
        loss = loss.sum() + self.KL_WEIGHT * sym_kl + self.COUNT_CONS_WEIGHT * cons
        logs = {"profile_mnll": profile_loss.detach(), "count_mse": count_loss.detach(),
                "rc_sym_kl": sym_kl.detach(), "rc_count_cons": cons.detach()}
        # Non-finite guard: one fp16 batch that overflows must not end the run. The batch counts as loss 0 and its
        # non-finite gradients make the loss scaler skip the step. 50 in a row means the weights really diverged:
        # the true loss is returned and the trainer stops the run.
        finite = torch.isfinite(loss)
        if bool(finite):
            self._nonfinite_streak = 0
        else:
            self._nonfinite_streak = getattr(self, "_nonfinite_streak", 0) + 1
            if self._nonfinite_streak < 50:
                loss = torch.where(finite, loss, torch.zeros_like(loss))
                logs = {k: torch.nan_to_num(torch.as_tensor(v, dtype=torch.float32), nan=0.0, posinf=0.0, neginf=0.0)
                        for k, v in logs.items()}
        return loss, logs

    def end_epoch(self, epoch):
        if self.s0.requires_grad and self.s0.grad is not None and float(self.s0.grad.abs().mean()) < 1:
            self.s0.requires_grad_(False)
            self.s1.requires_grad_(False)

# --- block: model ---
WIDTH = 256
N_STAGES = 5


class CheriBlock(nn.Module):
    """Cherimoya's Cheri block (cherimoya/cheri.py at 8e4283f, pure PyTorch): a 3-tap dilated depthwise conv, a per-example
    layer norm over the whole (length, channel) plane, then an MLP (C -> 2C -> C, tanh GELU) added back with scale 0.15."""

    def __init__(self, channels, dilation=1, expansion=2, residual_scale=0.15, eps=1e-3):
        super().__init__()
        self.dilation, self.residual_scale, self.eps = dilation, residual_scale, eps
        self.conv_weight = nn.Parameter(torch.empty(3, channels))
        self.linear1 = nn.Linear(channels, expansion * channels, bias=False)
        self.linear2 = nn.Linear(expansion * channels, channels, bias=False)
        self.activation = nn.GELU(approximate="tanh")
        for w in (self.conv_weight, self.linear1.weight, self.linear2.weight):
            nn.init.trunc_normal_(w, std=0.02)

    def forward(self, x):                      # x: (B, C, L)
        c = x.shape[1]
        y = F.conv1d(x, self.conv_weight.t().unsqueeze(1).to(x.dtype), padding=self.dilation, dilation=self.dilation, groups=c)
        flat = y.reshape(y.shape[0], -1).float()
        y = ((flat - flat.mean(1, keepdim=True)) * (flat.var(1, keepdim=True, unbiased=False) + self.eps).rsqrt())
        y = y.reshape(x.shape).to(x.dtype).transpose(1, 2)
        y = self.linear2(self.activation(self.linear1(y))).transpose(1, 2)
        return x + y * self.residual_scale


def group_norm(channels, groups=8):
    while channels % groups:
        groups -= 1
    return nn.GroupNorm(groups, channels)


class StandardizedConv1d(nn.Conv1d):
    """CAPYBARA's weight-standardised 'same' convolution."""

    def __init__(self, cin, cout, k, dilation=1):
        super().__init__(cin, cout, k, padding=0, dilation=dilation, bias=True)
        self.scale = nn.Parameter(torch.ones(cout, 1, 1))

    def forward(self, x):
        w = self.weight
        var = w.var(dim=(1, 2), unbiased=False, keepdim=True)
        fan_in = self.in_channels * self.kernel_size[0]
        w = (w - w.mean(dim=(1, 2), keepdim=True)) * torch.rsqrt(torch.clamp(var * fan_in, min=1e-4)) * self.scale
        total = self.dilation[0] * (self.kernel_size[0] - 1)
        x = F.pad(x, (total // 2, total - total // 2))
        return F.conv1d(x, w.to(x.dtype), self.bias.to(x.dtype), dilation=self.dilation)


class ConvBlock(nn.Module):
    """CAPYBARA pre-activation conv block: norm -> GELU -> dropout -> conv."""

    def __init__(self, channels, k, dropout=0.1):
        super().__init__()
        self.norm, self.act, self.drop = group_norm(channels), nn.GELU(), nn.Dropout(dropout)
        self.conv = StandardizedConv1d(channels, channels, k)

    def forward(self, x):
        return self.conv(self.drop(self.act(self.norm(x))))


class HybridAttentionUnit(nn.Module):
    """CAPYBARA HybridAttentionUnit: a residual pair of conv blocks, then pre-norm multi-head self-attention and an MLP."""

    def __init__(self, channels, k=5, heads=4, mlp_ratio=2.0, dropout=0.1, attn_dropout=0.1):
        super().__init__()
        self.conv1, self.conv2 = ConvBlock(channels, k, dropout), ConvBlock(channels, k, dropout)
        self.attn_norm = group_norm(channels)
        self.attn = nn.MultiheadAttention(channels, heads, dropout=attn_dropout, batch_first=True)
        hidden = max(channels, int(channels * mlp_ratio))
        self.ffn_norm = group_norm(channels)
        self.ffn = nn.Sequential(nn.Linear(channels, hidden), nn.GELU(), nn.Dropout(dropout), nn.Linear(hidden, channels),
                                 nn.Dropout(dropout))

    def forward(self, x):
        x = x + self.conv2(self.conv1(x))
        y = self.attn_norm(x).transpose(1, 2)
        x = x + self.attn(y, y, y, need_weights=False)[0].transpose(1, 2)
        return x + self.ffn(self.ffn_norm(x).transpose(1, 2)).transpose(1, 2)


class Encoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES):
        super().__init__()
        self.stem = nn.Conv1d(4, width, 21, padding=10)
        nn.init.trunc_normal_(self.stem.weight, std=0.02)
        nn.init.zeros_(self.stem.bias)
        self.blocks = nn.ModuleList([CheriBlock(width) for _ in range(n_stages)])

    def forward(self, x):
        x = F.gelu(self.stem(x), approximate="tanh")
        skips = []
        for block in self.blocks:
            x = block(x)
            skips.append(x)
            x = F.avg_pool1d(x, 2, ceil_mode=True)
        return x, skips


class Bottleneck(nn.Module):
    def __init__(self, width=WIDTH, depth=3):
        super().__init__()
        self.cheri = CheriBlock(width)
        self.units = nn.Sequential(*[HybridAttentionUnit(width) for _ in range(depth)])

    def forward(self, x):
        return self.units(self.cheri(x))


class YCountHead(nn.Module):
    """CAPYBARA YCountHead: conv [128, 64] (kernel 5, GroupNorm, GELU, dropout, max-pool 2), adaptive average pool to 4
    bins, MLP [64] with LayerNorm, then one output: ln(total counts + 1)."""

    def __init__(self, width=WIDTH, convs=(128, 64), mlp=(64,), k=5, bins=4, dropout=0.1):
        super().__init__()
        layers, c = [], width
        for h in convs:
            layers += [nn.Conv1d(c, h, k, padding=k // 2, bias=False), group_norm(h), nn.GELU(), nn.Dropout(dropout),
                       nn.MaxPool1d(2, ceil_mode=True)]
            c = h
        self.convs, self.bins = nn.Sequential(*layers), bins
        layers, d = [], c * bins
        for h in mlp:
            layers += [nn.Linear(d, h), nn.LayerNorm(h), nn.GELU(), nn.Dropout(dropout)]
            d = h
        self.mlp = nn.Sequential(*layers, nn.Linear(d, 1))

    def forward(self, z):
        return self.mlp(F.adaptive_avg_pool1d(self.convs(z), self.bins).flatten(1))


class GatedSkipFusion(nn.Module):
    """up + 2*sigmoid(W[up; skip])*skip, W a zero-initialised kernel-1 conv, so the gate starts at 1."""

    def __init__(self, width=WIDTH):
        super().__init__()
        self.gate = nn.Conv1d(2 * width, width, 1)
        nn.init.zeros_(self.gate.weight)
        nn.init.zeros_(self.gate.bias)

    def forward(self, up, skip):
        return up + 2 * torch.sigmoid(self.gate(torch.cat([up, skip], 1))) * skip


class Decoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES, blocks_per_stage=2):
        super().__init__()
        self.fuse = nn.ModuleList([GatedSkipFusion(width) for _ in range(n_stages)])
        self.blocks = nn.ModuleList([nn.Sequential(*[CheriBlock(width) for _ in range(blocks_per_stage)])
                                     for _ in range(n_stages)])

    def forward(self, z, skips):
        x = z
        for fuse, blocks, skip in zip(self.fuse, self.blocks, reversed(skips)):
            x = F.interpolate(x, size=skip.shape[-1], mode="nearest")
            x = blocks(fuse(x, skip))
        return x


class ProfileHead(nn.Module):
    """Cherimoya's profile head: one kernel-75 conv, then the central 1,000 positions."""

    def __init__(self, width=WIDTH, k=75):
        super().__init__()
        self.conv = nn.Conv1d(width, 1, k, padding=k // 2)
        nn.init.trunc_normal_(self.conv.weight, std=0.02)
        nn.init.zeros_(self.conv.bias)

    def forward(self, h):
        start = (h.shape[-1] - OUT_LEN) // 2
        return self.conv(h)[..., start:start + OUT_LEN]


class CAPY(nn.Module):
    """CAPY baseline Y-net. In training mode the reverse complement of the first half of the batch is appended and its
    outputs are returned as 'profile_rc' / 'counts_rc' for the RC-pair losses; eval mode is a single plain pass."""

    def __init__(self):
        super().__init__()
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = YCountHead()
        self.decoder = Decoder()
        self.profile_head = ProfileHead()
        self.progress, self.epoch = 0.0, 0

    def _core(self, x):
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        counts = self.count_head(z)
        profile = self.profile_head(self.decoder(z, skips))
        return profile, counts

    def forward(self, x):
        if self.training:
            b = x.shape[0]
            h = b // 2
            xr = x[:h].flip(1).flip(2)          # ACGT -> TGCA (complement) and reversed positions
            profile, counts = self._core(torch.cat([x, xr], 0))
            return {"profile": profile[:b], "counts": counts[:b], "profile_rc": profile[b:], "counts_rc": counts[b:]}
        profile, counts = self._core(x)
        return {"profile": profile, "counts": counts}


def build_model():
    return CAPY()

# --- block: objective ---
class Objective(nn.Module):
    """Cherimoya's training loss (profile MNLL + count MSE with Kendall-Gal learned weights) plus run3's Siamese RC pairs:
    the RC copies of half the batch are supervised on the flipped targets, and a symmetric profile KL (weight 50) and a
    squared log-count consistency (weight 0.5) tie each pair together."""

    def __init__(self):
        super().__init__()
        self.s0 = nn.Parameter(torch.ones(1))
        self.s1 = nn.Parameter(torch.ones(1))

    def forward(self, out, y, is_peak, net):
        n = y.shape[0]
        profile_loss = mnll(out["profile"], y).mean()
        count_loss = ((log_total(y) - out["counts"].float()) ** 2).mean()
        consistency = torch.zeros((), device=y.device)
        if "profile_rc" in out:
            h = out["profile_rc"].shape[0]
            yh = y[:h]
            prc = mnll(out["profile_rc"], yh.flip(-1)).mean()
            crc = ((log_total(yh) - out["counts_rc"].float()) ** 2).mean()
            profile_loss = (profile_loss * n + prc * h) / (n + h)
            count_loss = (count_loss * n + crc * h) / (n + h)
            lp = torch.log_softmax(out["profile"][:h].float(), dim=-1)
            lq = torch.log_softmax(out["profile_rc"].float().flip(-1), dim=-1)
            kl = 0.5 * ((lp.exp() * (lp - lq)).sum(-1) + (lq.exp() * (lq - lp)).sum(-1)).mean()
            ccons = ((out["counts"][:h].float() - out["counts_rc"].float()) ** 2).mean()
            consistency = 50.0 * kl + 0.5 * ccons
        loss = profile_loss / (2 * self.s0 ** 2) + count_loss / (2 * self.s1 ** 2) + consistency
        if self.s0.requires_grad:
            loss = loss + torch.log(self.s0) ** 2 + torch.log(self.s1) ** 2
        loss = loss.sum()
        logs = {"profile_mnll": profile_loss.detach(), "count_mse": count_loss.detach(), "rc_consistency": consistency.detach()}
        # Non-finite guard: one fp16 batch that overflows must not end the run. The batch counts as loss 0 and its
        # non-finite gradients make the loss scaler skip the step. 50 in a row means the weights really diverged:
        # the true loss is returned and the trainer stops the run.
        finite = torch.isfinite(loss)
        if bool(finite):
            self._nonfinite_streak = 0
        else:
            self._nonfinite_streak = getattr(self, "_nonfinite_streak", 0) + 1
            if self._nonfinite_streak < 50:
                loss = torch.where(finite, loss, torch.zeros_like(loss))
                logs = {k: torch.nan_to_num(torch.as_tensor(v, dtype=torch.float32), nan=0.0, posinf=0.0, neginf=0.0)
                        for k, v in logs.items()}
        return loss, logs

    def end_epoch(self, epoch):
        if self.s0.requires_grad and self.s0.grad is not None and float(self.s0.grad.abs().mean()) < 1:
            self.s0.requires_grad_(False)
            self.s1.requires_grad_(False)

# --- block: model ---
WIDTH = 256
N_STAGES = 5
AUX_RES = (8, 4, 2)          # deep-supervision resolutions (bp per bin) of decoder stages 1, 2, 3


class CheriBlock(nn.Module):
    """Cherimoya's Cheri block (cherimoya/cheri.py at 8e4283f, pure PyTorch): a 3-tap dilated depthwise conv, a per-example
    layer norm over the whole (length, channel) plane, then an MLP (C -> 2C -> C, tanh GELU) added back with scale 0.15."""

    def __init__(self, channels, dilation=1, expansion=2, residual_scale=0.15, eps=1e-3):
        super().__init__()
        self.dilation, self.residual_scale, self.eps = dilation, residual_scale, eps
        self.conv_weight = nn.Parameter(torch.empty(3, channels))
        self.linear1 = nn.Linear(channels, expansion * channels, bias=False)
        self.linear2 = nn.Linear(expansion * channels, channels, bias=False)
        self.activation = nn.GELU(approximate="tanh")
        for w in (self.conv_weight, self.linear1.weight, self.linear2.weight):
            nn.init.trunc_normal_(w, std=0.02)

    def forward(self, x):                      # x: (B, C, L)
        c = x.shape[1]
        y = F.conv1d(x, self.conv_weight.t().unsqueeze(1).to(x.dtype), padding=self.dilation, dilation=self.dilation, groups=c)
        flat = y.reshape(y.shape[0], -1).float()
        y = ((flat - flat.mean(1, keepdim=True)) * (flat.var(1, keepdim=True, unbiased=False) + self.eps).rsqrt())
        y = y.reshape(x.shape).to(x.dtype).transpose(1, 2)
        y = self.linear2(self.activation(self.linear1(y))).transpose(1, 2)
        return x + y * self.residual_scale


def group_norm(channels, groups=8):
    while channels % groups:
        groups -= 1
    return nn.GroupNorm(groups, channels)


class StandardizedConv1d(nn.Conv1d):
    """CAPYBARA's weight-standardised 'same' convolution."""

    def __init__(self, cin, cout, k, dilation=1):
        super().__init__(cin, cout, k, padding=0, dilation=dilation, bias=True)
        self.scale = nn.Parameter(torch.ones(cout, 1, 1))

    def forward(self, x):
        w = self.weight
        var = w.var(dim=(1, 2), unbiased=False, keepdim=True)
        fan_in = self.in_channels * self.kernel_size[0]
        w = (w - w.mean(dim=(1, 2), keepdim=True)) * torch.rsqrt(torch.clamp(var * fan_in, min=1e-4)) * self.scale
        total = self.dilation[0] * (self.kernel_size[0] - 1)
        x = F.pad(x, (total // 2, total - total // 2))
        return F.conv1d(x, w.to(x.dtype), self.bias.to(x.dtype), dilation=self.dilation)


class ConvBlock(nn.Module):
    """CAPYBARA pre-activation conv block: norm -> GELU -> dropout -> conv."""

    def __init__(self, channels, k, dropout=0.1):
        super().__init__()
        self.norm, self.act, self.drop = group_norm(channels), nn.GELU(), nn.Dropout(dropout)
        self.conv = StandardizedConv1d(channels, channels, k)

    def forward(self, x):
        return self.conv(self.drop(self.act(self.norm(x))))


class HybridAttentionUnit(nn.Module):
    """CAPYBARA HybridAttentionUnit: a residual pair of conv blocks, then pre-norm multi-head self-attention and an MLP."""

    def __init__(self, channels, k=5, heads=4, mlp_ratio=2.0, dropout=0.1, attn_dropout=0.1):
        super().__init__()
        self.conv1, self.conv2 = ConvBlock(channels, k, dropout), ConvBlock(channels, k, dropout)
        self.attn_norm = group_norm(channels)
        self.attn = nn.MultiheadAttention(channels, heads, dropout=attn_dropout, batch_first=True)
        hidden = max(channels, int(channels * mlp_ratio))
        self.ffn_norm = group_norm(channels)
        self.ffn = nn.Sequential(nn.Linear(channels, hidden), nn.GELU(), nn.Dropout(dropout), nn.Linear(hidden, channels),
                                 nn.Dropout(dropout))

    def forward(self, x):
        x = x + self.conv2(self.conv1(x))
        y = self.attn_norm(x).transpose(1, 2)
        x = x + self.attn(y, y, y, need_weights=False)[0].transpose(1, 2)
        return x + self.ffn(self.ffn_norm(x).transpose(1, 2)).transpose(1, 2)


class Encoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES):
        super().__init__()
        self.stem = nn.Conv1d(4, width, 21, padding=10)
        nn.init.trunc_normal_(self.stem.weight, std=0.02)
        nn.init.zeros_(self.stem.bias)
        self.blocks = nn.ModuleList([CheriBlock(width) for _ in range(n_stages)])

    def forward(self, x):
        x = F.gelu(self.stem(x), approximate="tanh")
        skips = []
        for block in self.blocks:
            x = block(x)
            skips.append(x)
            x = F.avg_pool1d(x, 2, ceil_mode=True)
        return x, skips


class Bottleneck(nn.Module):
    def __init__(self, width=WIDTH, depth=3):
        super().__init__()
        self.cheri = CheriBlock(width)
        self.units = nn.Sequential(*[HybridAttentionUnit(width) for _ in range(depth)])

    def forward(self, x):
        return self.units(self.cheri(x))


class YCountHead(nn.Module):
    """CAPYBARA YCountHead: conv [128, 64] (kernel 5, GroupNorm, GELU, dropout, max-pool 2), adaptive average pool to 4
    bins, MLP [64] with LayerNorm, then one output: ln(total counts + 1)."""

    def __init__(self, width=WIDTH, convs=(128, 64), mlp=(64,), k=5, bins=4, dropout=0.1):
        super().__init__()
        layers, c = [], width
        for h in convs:
            layers += [nn.Conv1d(c, h, k, padding=k // 2, bias=False), group_norm(h), nn.GELU(), nn.Dropout(dropout),
                       nn.MaxPool1d(2, ceil_mode=True)]
            c = h
        self.convs, self.bins = nn.Sequential(*layers), bins
        layers, d = [], c * bins
        for h in mlp:
            layers += [nn.Linear(d, h), nn.LayerNorm(h), nn.GELU(), nn.Dropout(dropout)]
            d = h
        self.mlp = nn.Sequential(*layers, nn.Linear(d, 1))

    def forward(self, z):
        return self.mlp(F.adaptive_avg_pool1d(self.convs(z), self.bins).flatten(1))


class GatedSkipFusion(nn.Module):
    """up + 2*sigmoid(W[up; skip])*skip, W a zero-initialised kernel-1 conv, so the gate starts at 1."""

    def __init__(self, width=WIDTH):
        super().__init__()
        self.gate = nn.Conv1d(2 * width, width, 1)
        nn.init.zeros_(self.gate.weight)
        nn.init.zeros_(self.gate.bias)

    def forward(self, up, skip):
        return up + 2 * torch.sigmoid(self.gate(torch.cat([up, skip], 1))) * skip


class Decoder(nn.Module):
    """Returns the full-resolution features and the output of every stage (stage i ends at 2^(4-i) bp per position)."""

    def __init__(self, width=WIDTH, n_stages=N_STAGES, blocks_per_stage=2):
        super().__init__()
        self.fuse = nn.ModuleList([GatedSkipFusion(width) for _ in range(n_stages)])
        self.blocks = nn.ModuleList([nn.Sequential(*[CheriBlock(width) for _ in range(blocks_per_stage)])
                                     for _ in range(n_stages)])

    def forward(self, z, skips):
        x = z
        stages = []
        for fuse, blocks, skip in zip(self.fuse, self.blocks, reversed(skips)):
            x = F.interpolate(x, size=skip.shape[-1], mode="nearest")
            x = blocks(fuse(x, skip))
            stages.append(x)
        return x, stages


class ProfileHead(nn.Module):
    """Cherimoya's profile head: one kernel-75 conv, then the central 1,000 positions."""

    def __init__(self, width=WIDTH, k=75):
        super().__init__()
        self.conv = nn.Conv1d(width, 1, k, padding=k // 2)
        nn.init.trunc_normal_(self.conv.weight, std=0.02)
        nn.init.zeros_(self.conv.bias)

    def forward(self, h):
        start = (h.shape[-1] - OUT_LEN) // 2
        return self.conv(h)[..., start:start + OUT_LEN]


class AuxProfileHead(nn.Module):
    """Zero-initialised deep-supervision head at r bp per position: kernel-15 conv, then the bins covering the central
    1,000 bp (start rounded to the nearest bin)."""

    def __init__(self, r, width=WIDTH, k=15):
        super().__init__()
        self.conv = nn.Conv1d(width, 1, k, padding=k // 2)
        nn.init.zeros_(self.conv.weight)
        nn.init.zeros_(self.conv.bias)
        self.n_bins = OUT_LEN // r
        self.start = int(round(((2114 - OUT_LEN) / 2) / r))

    def forward(self, h):
        return self.conv(h)[..., self.start:self.start + self.n_bins]


class CAPY(nn.Module):
    def __init__(self):
        super().__init__()
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = YCountHead()
        self.decoder = Decoder()
        self.profile_head = ProfileHead()
        self.aux_heads = nn.ModuleList([AuxProfileHead(r) for r in AUX_RES])
        self.progress, self.epoch = 0.0, 0

    def forward(self, x):
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        counts = self.count_head(z)
        h, stages = self.decoder(z, skips)
        out = {"profile": self.profile_head(h), "counts": counts}
        if self.training:
            for i, (r, head) in enumerate(zip(AUX_RES, self.aux_heads)):
                out["aux_profile_%d" % r] = head(stages[i + 1])
        return out


def build_model():
    return CAPY()

# --- block: objective ---
class Objective(nn.Module):
    """Cherimoya's training loss (profile MNLL + count MSE with Kendall-Gal learned weights) plus deep supervision:
    MNLL of the auxiliary 8/4/2 bp profile heads on bin-summed targets, weight 0.5 (mean over heads), in the profile term."""

    AUX_RES = (8, 4, 2)

    def __init__(self):
        super().__init__()
        self.s0 = nn.Parameter(torch.ones(1))
        self.s1 = nn.Parameter(torch.ones(1))

    def forward(self, out, y, is_peak, net):
        profile_loss = mnll(out["profile"], y).mean()
        count_loss = ((log_total(y) - out["counts"].float()) ** 2).mean()
        aux = []
        for r in self.AUX_RES:
            key = "aux_profile_%d" % r
            if key in out:
                yb = y.reshape(y.shape[0], y.shape[1], -1, r).sum(-1)
                aux.append(mnll(out[key], yb).mean())
        aux_loss = sum(aux) / len(aux) if aux else torch.zeros((), device=y.device)
        loss = (profile_loss + 0.5 * aux_loss) / (2 * self.s0 ** 2) + count_loss / (2 * self.s1 ** 2)
        if self.s0.requires_grad:
            loss = loss + torch.log(self.s0) ** 2 + torch.log(self.s1) ** 2
        loss = loss.sum()
        logs = {"profile_mnll": profile_loss.detach(), "count_mse": count_loss.detach(),
                "aux_mnll": torch.as_tensor(aux_loss).detach()}
        # Non-finite guard: one fp16 batch that overflows must not end the run. The batch counts as loss 0 and its
        # non-finite gradients make the loss scaler skip the step. 50 in a row means the weights really diverged:
        # the true loss is returned and the trainer stops the run.
        finite = torch.isfinite(loss)
        if bool(finite):
            self._nonfinite_streak = 0
        else:
            self._nonfinite_streak = getattr(self, "_nonfinite_streak", 0) + 1
            if self._nonfinite_streak < 50:
                loss = torch.where(finite, loss, torch.zeros_like(loss))
                logs = {k: torch.nan_to_num(torch.as_tensor(v, dtype=torch.float32), nan=0.0, posinf=0.0, neginf=0.0)
                        for k, v in logs.items()}
        return loss, logs

    def end_epoch(self, epoch):
        if self.s0.requires_grad and self.s0.grad is not None and float(self.s0.grad.abs().mean()) < 1:
            self.s0.requires_grad_(False)
            self.s1.requires_grad_(False)

