        w = self.weight
        var = w.var(dim=(1, 2), unbiased=False, keepdim=True)
        fan_in = self.in_channels * self.kernel_size[0]
        w = (w - w.mean(dim=(1, 2), keepdim=True)) * torch.rsqrt(torch.clamp(var * fan_in, min=1e-4)) * self.scale
        total = self.dilation[0] * (self.kernel_size[0] - 1)
        x = F.pad(x, (total // 2, total - total // 2))
        return F.conv1d(x, w.to(x.dtype), self.bias.to(x.dtype), dilation=self.dilation)


class ConvBlock(nn.Module):
    """CAPYBARA pre-activation conv block: norm -> GELU -> dropout -> conv."""

    def __init__(self, channels, k, dropout=0.1):
        super().__init__()
        self.norm, self.act, self.drop = group_norm(channels), nn.GELU(), nn.Dropout(dropout)
        self.conv = StandardizedConv1d(channels, channels, k)

    def forward(self, x):
        return self.conv(self.drop(self.act(self.norm(x))))


class HybridAttentionUnit(nn.Module):
    """CAPYBARA HybridAttentionUnit: a residual pair of conv blocks, then pre-norm multi-head self-attention and an MLP."""

    def __init__(self, channels, k=5, heads=4, mlp_ratio=2.0, dropout=0.1, attn_dropout=0.1):
        super().__init__()
        self.conv1, self.conv2 = ConvBlock(channels, k, dropout), ConvBlock(channels, k, dropout)
        self.attn_norm = group_norm(channels)
        self.attn = nn.MultiheadAttention(channels, heads, dropout=attn_dropout, batch_first=True)
        hidden = max(channels, int(channels * mlp_ratio))
        self.ffn_norm = group_norm(channels)
        self.ffn = nn.Sequential(nn.Linear(channels, hidden), nn.GELU(), nn.Dropout(dropout), nn.Linear(hidden, channels),
                                 nn.Dropout(dropout))

    def forward(self, x):
        x = x + self.conv2(self.conv1(x))
        y = self.attn_norm(x).transpose(1, 2)
        x = x + self.attn(y, y, y, need_weights=False)[0].transpose(1, 2)
        return x + self.ffn(self.ffn_norm(x).transpose(1, 2)).transpose(1, 2)


class Encoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES):
        super().__init__()
        self.stem = nn.Conv1d(4, width, 21, padding=10)
        nn.init.trunc_normal_(self.stem.weight, std=0.02)
        nn.init.zeros_(self.stem.bias)
        self.blocks = nn.ModuleList([CheriBlock(width) for _ in range(n_stages)])

    def forward(self, x):
        x = F.gelu(self.stem(x), approximate="tanh")
        skips = []
        for block in self.blocks:
            x = block(x)
            skips.append(x)
            x = F.avg_pool1d(x, 2, ceil_mode=True)
        return x, skips


class Bottleneck(nn.Module):
    def __init__(self, width=WIDTH, depth=3):
        super().__init__()
        self.cheri = CheriBlock(width)
        self.units = nn.Sequential(*[HybridAttentionUnit(width) for _ in range(depth)])

    def forward(self, x):
        return self.units(self.cheri(x))


class YCountHead(nn.Module):
    """CAPYBARA YCountHead: conv [128, 64] (kernel 5, GroupNorm, GELU, dropout, max-pool 2), adaptive average pool to 4
    bins, MLP [64] with LayerNorm, then one output: ln(total counts + 1)."""

    def __init__(self, width=WIDTH, convs=(128, 64), mlp=(64,), k=5, bins=4, dropout=0.1):
        super().__init__()
        layers, c = [], width
        for h in convs:
            layers += [nn.Conv1d(c, h, k, padding=k // 2, bias=False), group_norm(h), nn.GELU(), nn.Dropout(dropout),
                       nn.MaxPool1d(2, ceil_mode=True)]
            c = h
        self.convs, self.bins = nn.Sequential(*layers), bins
        layers, d = [], c * bins
        for h in mlp:
            layers += [nn.Linear(d, h), nn.LayerNorm(h), nn.GELU(), nn.Dropout(dropout)]
            d = h
        self.mlp = nn.Sequential(*layers, nn.Linear(d, 1))

    def forward(self, z):
        return self.mlp(F.adaptive_avg_pool1d(self.convs(z), self.bins).flatten(1))


class GatedSkipFusion(nn.Module):
    """up + 2*sigmoid(W[up; skip])*skip, W a zero-initialised kernel-1 conv, so the gate starts at 1."""

    def __init__(self, width=WIDTH):
        super().__init__()
        self.gate = nn.Conv1d(2 * width, width, 1)
        nn.init.zeros_(self.gate.weight)
        nn.init.zeros_(self.gate.bias)

    def forward(self, up, skip):
        return up + 2 * torch.sigmoid(self.gate(torch.cat([up, skip], 1))) * skip


class Decoder(nn.Module):
    """Returns the full-resolution features and the output of every stage (stage i ends at 2^(4-i) bp per position)."""

    def __init__(self, width=WIDTH, n_stages=N_STAGES, blocks_per_stage=2):
        super().__init__()
        self.fuse = nn.ModuleList([GatedSkipFusion(width) for _ in range(n_stages)])
        self.blocks = nn.ModuleList([nn.Sequential(*[CheriBlock(width) for _ in range(blocks_per_stage)])
                                     for _ in range(n_stages)])

    def forward(self, z, skips):
        x = z
        stages = []
        for fuse, blocks, skip in zip(self.fuse, self.blocks, reversed(skips)):
            x = F.interpolate(x, size=skip.shape[-1], mode="nearest")
            x = blocks(fuse(x, skip))
            stages.append(x)
        return x, stages


class ProfileHead(nn.Module):
    """Cherimoya's profile head: one kernel-75 conv, then the central 1,000 positions."""

    def __init__(self, width=WIDTH, k=75):
        super().__init__()
        self.conv = nn.Conv1d(width, 1, k, padding=k // 2)
        nn.init.trunc_normal_(self.conv.weight, std=0.02)
        nn.init.zeros_(self.conv.bias)

    def forward(self, h):
        start = (h.shape[-1] - OUT_LEN) // 2
        return self.conv(h)[..., start:start + OUT_LEN]


class AuxProfileHead(nn.Module):
    """Zero-initialised deep-supervision head at r bp per position: kernel-15 conv, then the bins covering the central
    1,000 bp (start rounded to the nearest bin)."""

    def __init__(self, r, width=WIDTH, k=15):
        super().__init__()
        self.conv = nn.Conv1d(width, 1, k, padding=k // 2)
        nn.init.zeros_(self.conv.weight)
        nn.init.zeros_(self.conv.bias)
        self.n_bins = OUT_LEN // r
        self.start = int(round(((2114 - OUT_LEN) / 2) / r))

    def forward(self, h):
        return self.conv(h)[..., self.start:self.start + self.n_bins]


class CAPY(nn.Module):
    """CAPY baseline Y-net with deep supervision and Siamese RC pairs: in training mode the reverse complement of the
    first half of the batch is appended; its outputs are returned (in RC coordinates) as 'profile_rc' / 'counts_rc'.
    Auxiliary deep-supervision heads are applied to the forward copies only. Eval is a single plain pass."""

    def __init__(self):
        super().__init__()
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = YCountHead()
        self.decoder = Decoder()
        self.profile_head = ProfileHead()
        self.aux_heads = nn.ModuleList([AuxProfileHead(r) for r in AUX_RES])
        self.progress, self.epoch = 0.0, 0

    def _core(self, x):
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        counts = self.count_head(z)
        h, stages = self.decoder(z, skips)
        return self.profile_head(h), counts, stages

    def forward(self, x):
        if self.training and x.shape[0] >= 2:
            b = x.shape[0]
            half = b // 2
            xr = x[:half].flip(1).flip(2)          # ACGT -> TGCA (complement) and reversed positions
            profile, counts, stages = self._core(torch.cat([x, xr], 0))
            out = {"profile": profile[:b], "counts": counts[:b], "profile_rc": profile[b:], "counts_rc": counts[b:]}
            for i, (r, head) in enumerate(zip(AUX_RES, self.aux_heads)):
                out["aux_profile_%d" % r] = head(stages[i + 1][:b])
            return out
        profile, counts, stages = self._core(x)
        out = {"profile": profile, "counts": counts}
        if self.training:
            for i, (r, head) in enumerate(zip(AUX_RES, self.aux_heads)):
                out["aux_profile_%d" % r] = head(stages[i + 1])
        return out


def build_model():
    return CAPY()

# --- block: objective ---
class Objective(nn.Module):
    """Cherimoya's training loss (profile MNLL + count MSE with Kendall-Gal learned weights) plus deep supervision
    (MNLL of the 8/4/2 bp auxiliary heads on bin-summed targets, weight 0.5) plus run3's Siamese RC pairs: the RC copies
    of half the batch are supervised on the flipped targets, with a symmetric profile KL (weight 50) and a squared
    log-count consistency (weight 0.5) between each locus and its RC copy."""

    AUX_RES = (8, 4, 2)

    def __init__(self, kl_weight=50.0, count_cons_weight=0.5):
        super().__init__()
        self.s0 = nn.Parameter(torch.ones(1))
        self.s1 = nn.Parameter(torch.ones(1))
        self.kl_weight, self.count_cons_weight = kl_weight, count_cons_weight

    def forward(self, out, y, is_peak, net):
        profile, counts = out["profile"], out["counts"]
        h = 0
        if "profile_rc" in out and out["profile_rc"].shape[0] > 0:
            rp, rc = out["profile_rc"], out["counts_rc"]
            h = rp.shape[0]
            all_profile = torch.cat([profile, rp], 0)
            all_counts = torch.cat([counts, rc], 0)
            all_y = torch.cat([y, y[:h].flip(-1)], 0)
        else:
            all_profile, all_counts, all_y = profile, counts, y
        profile_loss = mnll(all_profile, all_y).mean()
        count_loss = ((log_total(all_y) - all_counts.float()) ** 2).mean()
        aux = []
        for r in self.AUX_RES:
            key = "aux_profile_%d" % r
            if key in out:
                yb = y.reshape(y.shape[0], y.shape[1], -1, r).sum(-1)
                aux.append(mnll(out[key], yb).mean())
        aux_loss = sum(aux) / len(aux) if aux else torch.zeros((), device=y.device)
        loss = (profile_loss + 0.5 * aux_loss) / (2 * self.s0 ** 2) + count_loss / (2 * self.s1 ** 2)
        if self.s0.requires_grad:
            loss = loss + torch.log(self.s0) ** 2 + torch.log(self.s1) ** 2
        loss = loss.sum()
        logs = {"profile_mnll": profile_loss.detach(), "count_mse": count_loss.detach(),
                "aux_mnll": torch.as_tensor(aux_loss).detach()}
        if h > 0:
            lp = F.log_softmax(profile[:h].float().flatten(1), dim=-1)
            lr = F.log_softmax(rp.flip(-1).float().flatten(1), dim=-1)
            kl = 0.5 * ((lp.exp() * (lp - lr)).sum(-1) + (lr.exp() * (lr - lp)).sum(-1)).mean()
            cons = ((counts[:h].float() - rc.float()) ** 2).mean()
            loss = loss + self.kl_weight * kl + self.count_cons_weight * cons
            logs["rc_kl"] = kl.detach()
            logs["rc_count_cons"] = cons.detach()
        # Non-finite guard: one fp16 batch that overflows must not end the run. The batch counts as loss 0 and its
        # non-finite gradients make the loss scaler skip the step. 50 in a row means the weights really diverged:
        # the true loss is returned and the trainer stops the run.
        finite = torch.isfinite(loss)
        if bool(finite):
            self._nonfinite_streak = 0
        else:
            self._nonfinite_streak = getattr(self, "_nonfinite_streak", 0) + 1
            if self._nonfinite_streak < 50:
                loss = torch.where(finite, loss, torch.zeros_like(loss))
                logs = {k: torch.nan_to_num(torch.as_tensor(v, dtype=torch.float32), nan=0.0, posinf=0.0, neginf=0.0)
                        for k, v in logs.items()}
        return loss, logs

    def end_epoch(self, epoch):
        if self.s0.requires_grad and self.s0.grad is not None and float(self.s0.grad.abs().mean()) < 1:
            self.s0.requires_grad_(False)
            self.s1.requires_grad_(False)

# --- block: model ---
WIDTH = 256
N_STAGES = 5
AUX_RES = (8, 4, 2)          # deep-supervision resolutions (bp per bin) of decoder stages 1, 2, 3


class CheriBlock(nn.Module):
    # Cherimoya's Cheri block: 3-tap dilated depthwise conv, per-example layer norm over (L, C), MLP C->2C->C, scale 0.15.

    def __init__(self, channels, dilation=1, expansion=2, residual_scale=0.15, eps=1e-3):
        super().__init__()
        self.dilation, self.residual_scale, self.eps = dilation, residual_scale, eps
        self.conv_weight = nn.Parameter(torch.empty(3, channels))
        self.linear1 = nn.Linear(channels, expansion * channels, bias=False)
        self.linear2 = nn.Linear(expansion * channels, channels, bias=False)
        self.activation = nn.GELU(approximate='tanh')
        for w in (self.conv_weight, self.linear1.weight, self.linear2.weight):
            nn.init.trunc_normal_(w, std=0.02)

    def forward(self, x):
        c = x.shape[1]
        y = F.conv1d(x, self.conv_weight.t().unsqueeze(1).to(x.dtype), padding=self.dilation, dilation=self.dilation, groups=c)
        flat = y.reshape(y.shape[0], -1).float()
        y = ((flat - flat.mean(1, keepdim=True)) * (flat.var(1, keepdim=True, unbiased=False) + self.eps).rsqrt())
        y = y.reshape(x.shape).to(x.dtype).transpose(1, 2)
        y = self.linear2(self.activation(self.linear1(y))).transpose(1, 2)
        return x + y * self.residual_scale


def group_norm(channels, groups=8):
    while channels % groups:
        groups -= 1
    return nn.GroupNorm(groups, channels)


class StandardizedConv1d(nn.Conv1d):
    def __init__(self, cin, cout, k, dilation=1):
        super().__init__(cin, cout, k, padding=0, dilation=dilation, bias=True)
        self.scale = nn.Parameter(torch.ones(cout, 1, 1))

    def forward(self, x):
        w = self.weight
        var = w.var(dim=(1, 2), unbiased=False, keepdim=True)
        fan_in = self.in_channels * self.kernel_size[0]
        w = (w - w.mean(dim=(1, 2), keepdim=True)) * torch.rsqrt(torch.clamp(var * fan_in, min=1e-4)) * self.scale
        total = self.dilation[0] * (self.kernel_size[0] - 1)
        x = F.pad(x, (total // 2, total - total // 2))
        return F.conv1d(x, w.to(x.dtype), self.bias.to(x.dtype), dilation=self.dilation)


class ConvBlock(nn.Module):
    def __init__(self, channels, k, dropout=0.1):
        super().__init__()
        self.norm, self.act, self.drop = group_norm(channels), nn.GELU(), nn.Dropout(dropout)
        self.conv = StandardizedConv1d(channels, channels, k)

    def forward(self, x):
        return self.conv(self.drop(self.act(self.norm(x))))


class HybridAttentionUnit(nn.Module):
    def __init__(self, channels, k=5, heads=4, mlp_ratio=2.0, dropout=0.1, attn_dropout=0.1):
        super().__init__()
        self.conv1, self.conv2 = ConvBlock(channels, k, dropout), ConvBlock(channels, k, dropout)
        self.attn_norm = group_norm(channels)
        self.attn = nn.MultiheadAttention(channels, heads, dropout=attn_dropout, batch_first=True)
        hidden = max(channels, int(channels * mlp_ratio))
        self.ffn_norm = group_norm(channels)
        self.ffn = nn.Sequential(nn.Linear(channels, hidden), nn.GELU(), nn.Dropout(dropout), nn.Linear(hidden, channels),
                                 nn.Dropout(dropout))

    def forward(self, x):
        x = x + self.conv2(self.conv1(x))
        y = self.attn_norm(x).transpose(1, 2)
        x = x + self.attn(y, y, y, need_weights=False)[0].transpose(1, 2)
        return x + self.ffn(self.ffn_norm(x).transpose(1, 2)).transpose(1, 2)


class Encoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES):
        super().__init__()
        self.stem = nn.Conv1d(4, width, 21, padding=10)
        nn.init.trunc_normal_(self.stem.weight, std=0.02)
        nn.init.zeros_(self.stem.bias)
        self.blocks = nn.ModuleList([CheriBlock(width) for _ in range(n_stages)])

    def forward(self, x):
        x = F.gelu(self.stem(x), approximate='tanh')
        skips = []
        for block in self.blocks:
            x = block(x)
            skips.append(x)
            x = F.avg_pool1d(x, 2, ceil_mode=True)
        return x, skips


class Bottleneck(nn.Module):
    def __init__(self, width=WIDTH, depth=3):
        super().__init__()
        self.cheri = CheriBlock(width)
        self.units = nn.Sequential(*[HybridAttentionUnit(width) for _ in range(depth)])

    def forward(self, x):
        return self.units(self.cheri(x))


class YCountHead(nn.Module):
    def __init__(self, width=WIDTH, convs=(128, 64), mlp=(64,), k=5, bins=4, dropout=0.1):
        super().__init__()
        layers, c = [], width
        for h in convs:
            layers += [nn.Conv1d(c, h, k, padding=k // 2, bias=False), group_norm(h), nn.GELU(), nn.Dropout(dropout),
                       nn.MaxPool1d(2, ceil_mode=True)]
            c = h
        self.convs, self.bins = nn.Sequential(*layers), bins
        layers, d = [], c * bins
        for h in mlp:
            layers += [nn.Linear(d, h), nn.LayerNorm(h), nn.GELU(), nn.Dropout(dropout)]
            d = h
        self.mlp = nn.Sequential(*layers, nn.Linear(d, 1))

    def forward(self, z):
        return self.mlp(F.adaptive_avg_pool1d(self.convs(z), self.bins).flatten(1))


class GatedSkipFusion(nn.Module):
    def __init__(self, width=WIDTH):
        super().__init__()
        self.gate = nn.Conv1d(2 * width, width, 1)
        nn.init.zeros_(self.gate.weight)
        nn.init.zeros_(self.gate.bias)

    def forward(self, up, skip):
        return up + 2 * torch.sigmoid(self.gate(torch.cat([up, skip], 1))) * skip


class Decoder(nn.Module):
    # Returns the full-resolution features and every stage's output (stage i ends at 2^(4-i) bp per position).

    def __init__(self, width=WIDTH, n_stages=N_STAGES, blocks_per_stage=2):
        super().__init__()
        self.fuse = nn.ModuleList([GatedSkipFusion(width) for _ in range(n_stages)])
        self.blocks = nn.ModuleList([nn.Sequential(*[CheriBlock(width) for _ in range(blocks_per_stage)])
                                     for _ in range(n_stages)])

    def forward(self, z, skips):
        x = z
        stages = []
        for fuse, blocks, skip in zip(self.fuse, self.blocks, reversed(skips)):
            x = F.interpolate(x, size=skip.shape[-1], mode='nearest')
            x = blocks(fuse(x, skip))
            stages.append(x)
        return x, stages


class ProfileHead(nn.Module):
    def __init__(self, width=WIDTH, k=75):
        super().__init__()
        self.conv = nn.Conv1d(width, 1, k, padding=k // 2)
        nn.init.trunc_normal_(self.conv.weight, std=0.02)
        nn.init.zeros_(self.conv.bias)

    def forward(self, h):
        start = (h.shape[-1] - OUT_LEN) // 2
        return self.conv(h)[..., start:start + OUT_LEN]


class AuxProfileHead(nn.Module):
    # Zero-initialised deep-supervision head at r bp per position: kernel-15 conv, then the bins covering the central 1,000 bp.

    def __init__(self, r, width=WIDTH, k=15):
        super().__init__()
        self.conv = nn.Conv1d(width, 1, k, padding=k // 2)
        nn.init.zeros_(self.conv.weight)
        nn.init.zeros_(self.conv.bias)
        self.n_bins = OUT_LEN // r
        self.start = int(round(((2114 - OUT_LEN) / 2) / r))

    def forward(self, h):
        return self.conv(h)[..., self.start:self.start + self.n_bins]


class CAPY(nn.Module):
    def __init__(self):
        super().__init__()
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = YCountHead()
        self.decoder = Decoder()
        self.profile_head = ProfileHead()
        self.aux_heads = nn.ModuleList([AuxProfileHead(r) for r in AUX_RES])
        self.progress, self.epoch = 0.0, 0

    def forward(self, x):
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        counts = self.count_head(z)
        h, stages = self.decoder(z, skips)
        profile = self.profile_head(h)
        out = {'profile': profile, 'counts': counts}
        for i, (r, head) in enumerate(zip(AUX_RES, self.aux_heads)):
            out['aux_%d' % r] = head(stages[i + 1])
        return out


def build_model():
    return CAPY()

# --- block: objective ---
class Objective(nn.Module):
    # Cherimoya loss (profile MNLL + count MSE, Kendall-Gal weights) + 100 * Pearson profile term + deep supervision:
    # MNLL of each auxiliary head on bin-summed targets, weight 0.5 each.

    def __init__(self):
        super().__init__()
        self.s0 = nn.Parameter(torch.ones(1))
        self.s1 = nn.Parameter(torch.ones(1))

    def forward(self, out, y, is_peak, net):
        profile_loss = mnll(out['profile'], y).mean()
        count_loss = ((log_total(y) - out['counts'].float()) ** 2).mean()
        p = torch.softmax(out['profile'].float(), dim=-1)
        t = y.float()
        pc = p - p.mean(-1, keepdim=True)
        tc = t - t.mean(-1, keepdim=True)
        r = (pc * tc).sum(-1) / torch.sqrt((pc * pc).sum(-1) * (tc * tc).sum(-1) + 1e-8)
        pearson_loss = (1.0 - r).mean()
        aux_loss = torch.zeros((), device=y.device, dtype=torch.float32)
        for res in (8, 4, 2):
            key = 'aux_%d' % res
            if key in out:
                a = out[key].float()
                n = a.shape[-1]
                yb = t[..., :n * res].reshape(t.shape[0], t.shape[1], n, res).sum(-1)
                aux_loss = aux_loss + mnll(a, yb).mean()
        loss = profile_loss / (2 * self.s0 ** 2) + count_loss / (2 * self.s1 ** 2) + 100.0 * pearson_loss + 0.5 * aux_loss
        if self.s0.requires_grad:
            loss = loss + torch.log(self.s0) ** 2 + torch.log(self.s1) ** 2
        loss = loss.sum()
        logs = {'profile_mnll': profile_loss.detach(), 'count_mse': count_loss.detach(), 'pearson_loss': pearson_loss.detach(),
                'aux_mnll': aux_loss.detach()}
        # Non-finite guard: one fp16 batch that overflows must not end the run. The batch counts as loss 0 and its
        # non-finite gradients make the loss scaler skip the step. 50 in a row means the weights really diverged:
        # the true loss is returned and the trainer stops the run.
        finite = torch.isfinite(loss)
        if bool(finite):
            self._nonfinite_streak = 0
        else:
            self._nonfinite_streak = getattr(self, '_nonfinite_streak', 0) + 1
            if self._nonfinite_streak < 50:
                loss = torch.where(finite, loss, torch.zeros_like(loss))
                logs = {k: torch.nan_to_num(torch.as_tensor(v, dtype=torch.float32), nan=0.0, posinf=0.0, neginf=0.0)
                        for k, v in logs.items()}
        return loss, logs

    def end_epoch(self, epoch):
        if self.s0.requires_grad and self.s0.grad is not None and float(self.s0.grad.abs().mean()) < 1:
            self.s0.requires_grad_(False)
            self.s1.requires_grad_(False)

# --- block: model ---
WIDTH = 256
N_STAGES = 5
AUX_RES = (8, 4, 2)          # deep-supervision resolutions (bp per bin) of decoder stages 1, 2, 3


class CheriBlock(nn.Module):
    """Cherimoya's Cheri block (cherimoya/cheri.py at 8e4283f, pure PyTorch): a 3-tap dilated depthwise conv, a per-example
    layer norm over the whole (length, channel) plane, then an MLP (C -> 2C -> C, tanh GELU) added back with scale 0.15."""

    def __init__(self, channels, dilation=1, expansion=2, residual_scale=0.15, eps=1e-3):
        super().__init__()
        self.dilation, self.residual_scale, self.eps = dilation, residual_scale, eps
        self.conv_weight = nn.Parameter(torch.empty(3, channels))
        self.linear1 = nn.Linear(channels, expansion * channels, bias=False)
        self.linear2 = nn.Linear(expansion * channels, channels, bias=False)
        self.activation = nn.GELU(approximate="tanh")
        for w in (self.conv_weight, self.linear1.weight, self.linear2.weight):
            nn.init.trunc_normal_(w, std=0.02)

    def forward(self, x):                      # x: (B, C, L)
        c = x.shape[1]
        y = F.conv1d(x, self.conv_weight.t().unsqueeze(1).to(x.dtype), padding=self.dilation, dilation=self.dilation, groups=c)
        flat = y.reshape(y.shape[0], -1).float()
        y = ((flat - flat.mean(1, keepdim=True)) * (flat.var(1, keepdim=True, unbiased=False) + self.eps).rsqrt())
        y = y.reshape(x.shape).to(x.dtype).transpose(1, 2)
        y = self.linear2(self.activation(self.linear1(y))).transpose(1, 2)
        return x + y * self.residual_scale


def group_norm(channels, groups=8):
    while channels % groups:
        groups -= 1
    return nn.GroupNorm(groups, channels)


class StandardizedConv1d(nn.Conv1d):
    """CAPYBARA's weight-standardised 'same' convolution."""

    def __init__(self, cin, cout, k, dilation=1):
        super().__init__(cin, cout, k, padding=0, dilation=dilation, bias=True)
        self.scale = nn.Parameter(torch.ones(cout, 1, 1))

    def forward(self, x):
        w = self.weight
        var = w.var(dim=(1, 2), unbiased=False, keepdim=True)
        fan_in = self.in_channels * self.kernel_size[0]
        w = (w - w.mean(dim=(1, 2), keepdim=True)) * torch.rsqrt(torch.clamp(var * fan_in, min=1e-4)) * self.scale
        total = self.dilation[0] * (self.kernel_size[0] - 1)
        x = F.pad(x, (total // 2, total - total // 2))
        return F.conv1d(x, w.to(x.dtype), self.bias.to(x.dtype), dilation=self.dilation)


class ConvBlock(nn.Module):
    """CAPYBARA pre-activation conv block: norm -> GELU -> dropout -> conv."""

    def __init__(self, channels, k, dropout=0.1):
        super().__init__()
        self.norm, self.act, self.drop = group_norm(channels), nn.GELU(), nn.Dropout(dropout)
        self.conv = StandardizedConv1d(channels, channels, k)

    def forward(self, x):
        return self.conv(self.drop(self.act(self.norm(x))))


class HybridAttentionUnit(nn.Module):
    """CAPYBARA HybridAttentionUnit: a residual pair of conv blocks, then pre-norm multi-head self-attention and an MLP."""

    def __init__(self, channels, k=5, heads=4, mlp_ratio=2.0, dropout=0.1, attn_dropout=0.1):
        super().__init__()
        self.conv1, self.conv2 = ConvBlock(channels, k, dropout), ConvBlock(channels, k, dropout)
        self.attn_norm = group_norm(channels)
        self.attn = nn.MultiheadAttention(channels, heads, dropout=attn_dropout, batch_first=True)
        hidden = max(channels, int(channels * mlp_ratio))
        self.ffn_norm = group_norm(channels)
        self.ffn = nn.Sequential(nn.Linear(channels, hidden), nn.GELU(), nn.Dropout(dropout), nn.Linear(hidden, channels),
                                 nn.Dropout(dropout))

    def forward(self, x):
        x = x + self.conv2(self.conv1(x))
        y = self.attn_norm(x).transpose(1, 2)
        x = x + self.attn(y, y, y, need_weights=False)[0].transpose(1, 2)
        return x + self.ffn(self.ffn_norm(x).transpose(1, 2)).transpose(1, 2)


class Encoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES):
        super().__init__()
        self.stem = nn.Conv1d(4, width, 21, padding=10)
        nn.init.trunc_normal_(self.stem.weight, std=0.02)
        nn.init.zeros_(self.stem.bias)
        self.blocks = nn.ModuleList([CheriBlock(width) for _ in range(n_stages)])

    def forward(self, x):
        x = F.gelu(self.stem(x), approximate="tanh")
        skips = []
        for block in self.blocks:
            x = block(x)
            skips.append(x)
            x = F.avg_pool1d(x, 2, ceil_mode=True)
        return x, skips


class Bottleneck(nn.Module):
    def __init__(self, width=WIDTH, depth=3):
        super().__init__()
        self.cheri = CheriBlock(width)
        self.units = nn.Sequential(*[HybridAttentionUnit(width) for _ in range(depth)])

    def forward(self, x):
        return self.units(self.cheri(x))


class YCountHead(nn.Module):
    """CAPYBARA YCountHead: conv [128, 64] (kernel 5, GroupNorm, GELU, dropout, max-pool 2), adaptive average pool to 4
    bins, MLP [64] with LayerNorm, then one output: ln(total counts + 1)."""

    def __init__(self, width=WIDTH, convs=(128, 64), mlp=(64,), k=5, bins=4, dropout=0.1):
        super().__init__()
        layers, c = [], width
        for h in convs:
            layers += [nn.Conv1d(c, h, k, padding=k // 2, bias=False), group_norm(h), nn.GELU(), nn.Dropout(dropout),
                       nn.MaxPool1d(2, ceil_mode=True)]
            c = h
        self.convs, self.bins = nn.Sequential(*layers), bins
        layers, d = [], c * bins
        for h in mlp:
            layers += [nn.Linear(d, h), nn.LayerNorm(h), nn.GELU(), nn.Dropout(dropout)]
            d = h
        self.mlp = nn.Sequential(*layers, nn.Linear(d, 1))

    def forward(self, z):
        return self.mlp(F.adaptive_avg_pool1d(self.convs(z), self.bins).flatten(1))


class GatedSkipFusion(nn.Module):
    """up + 2*sigmoid(W[up; skip])*skip, W a zero-initialised kernel-1 conv, so the gate starts at 1."""

    def __init__(self, width=WIDTH):
        super().__init__()
        self.gate = nn.Conv1d(2 * width, width, 1)
        nn.init.zeros_(self.gate.weight)
        nn.init.zeros_(self.gate.bias)

    def forward(self, up, skip):
        return up + 2 * torch.sigmoid(self.gate(torch.cat([up, skip], 1))) * skip


class Decoder(nn.Module):
    """Returns the full-resolution features and the output of every stage (stage i ends at 2^(4-i) bp per position)."""

    def __init__(self, width=WIDTH, n_stages=N_STAGES, blocks_per_stage=2):
        super().__init__()
        self.fuse = nn.ModuleList([GatedSkipFusion(width) for _ in range(n_stages)])
        self.blocks = nn.ModuleList([nn.Sequential(*[CheriBlock(width) for _ in range(blocks_per_stage)])
                                     for _ in range(n_stages)])

    def forward(self, z, skips):
        x = z
        stages = []
        for fuse, blocks, skip in zip(self.fuse, self.blocks, reversed(skips)):
            x = F.interpolate(x, size=skip.shape[-1], mode="nearest")
            x = blocks(fuse(x, skip))
            stages.append(x)
        return x, stages


class ProfileHead(nn.Module):
    """Cherimoya's profile head: one kernel-75 conv, then the central 1,000 positions."""

    def __init__(self, width=WIDTH, k=75):
        super().__init__()
        self.conv = nn.Conv1d(width, 1, k, padding=k // 2)
        nn.init.trunc_normal_(self.conv.weight, std=0.02)
        nn.init.zeros_(self.conv.bias)

    def forward(self, h):
        start = (h.shape[-1] - OUT_LEN) // 2
        return self.conv(h)[..., start:start + OUT_LEN]


class AuxProfileHead(nn.Module):
    """Zero-initialised deep-supervision head at r bp per position: kernel-15 conv, then the bins covering the central
    1,000 bp (start rounded to the nearest bin)."""

    def __init__(self, r, width=WIDTH, k=15):
        super().__init__()
        self.conv = nn.Conv1d(width, 1, k, padding=k // 2)
        nn.init.zeros_(self.conv.weight)
        nn.init.zeros_(self.conv.bias)
        self.n_bins = OUT_LEN // r
        self.start = int(round(((2114 - OUT_LEN) / 2) / r))

    def forward(self, h):
        return self.conv(h)[..., self.start:self.start + self.n_bins]


class CAPY(nn.Module):
    def __init__(self):
        super().__init__()
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = YCountHead()
        self.decoder = Decoder()
        self.profile_head = ProfileHead()
        self.aux_heads = nn.ModuleList([AuxProfileHead(r) for r in AUX_RES])
        self.progress, self.epoch = 0.0, 0

    def forward(self, x):
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        counts = self.count_head(z)
        h, stages = self.decoder(z, skips)
        profile = self.profile_head(h)
        out = {"profile": profile, "counts": counts}
        if self.training:
            for r, head, st in zip(AUX_RES, self.aux_heads, stages[1:4]):
                out["aux_profile_%d" % r] = head(st)
        return out


def build_model():
    return CAPY()

# --- block: objective ---
class Objective(nn.Module):
    """Cherimoya's training loss (profile MNLL + count MSE with Kendall-Gal learned weights) plus run3's Pearson profile
    term (100 * (1 - Pearson(softmax(logits), y)), float32) and deep supervision: MNLL of the 8/4/2 bp auxiliary heads
    on bin-summed targets, weight 0.5, inside the profile term."""

    AUX_RES = (8, 4, 2)

    def __init__(self):
        super().__init__()
        self.s0 = nn.Parameter(torch.ones(1))
        self.s1 = nn.Parameter(torch.ones(1))

    def forward(self, out, y, is_peak, net):
        profile_loss = mnll(out["profile"], y).mean()
        count_loss = ((log_total(y) - out["counts"].float()) ** 2).mean()
        p = torch.softmax(out["profile"].float(), dim=-1)
        t = y.float()
        pc = p - p.mean(-1, keepdim=True)
        tc = t - t.mean(-1, keepdim=True)
        r = (pc * tc).sum(-1) / torch.sqrt((pc * pc).sum(-1) * (tc * tc).sum(-1) + 1e-8)
        pearson_loss = (1.0 - r).mean()
        aux = []
        for res in self.AUX_RES:
            key = "aux_profile_%d" % res
            if key in out:
                yb = y.reshape(y.shape[0], y.shape[1], -1, res).sum(-1)
                aux.append(mnll(out[key].float(), yb).mean())
        aux_loss = sum(aux) / len(aux) if aux else torch.zeros((), device=y.device)
        loss = (profile_loss + 0.5 * aux_loss) / (2 * self.s0 ** 2) + count_loss / (2 * self.s1 ** 2) + 100.0 * pearson_loss
        if self.s0.requires_grad:
            loss = loss + torch.log(self.s0) ** 2 + torch.log(self.s1) ** 2
        loss = loss.sum()
        logs = {"profile_mnll": profile_loss.detach(), "count_mse": count_loss.detach(), "pearson_loss": pearson_loss.detach(),
                "aux_mnll": torch.as_tensor(aux_loss).detach()}
        # Non-finite guard: one fp16 batch that overflows must not end the run. The batch counts as loss 0 and its
        # non-finite gradients make the loss scaler skip the step. 50 in a row means the weights really diverged:
        # the true loss is returned and the trainer stops the run.
        finite = torch.isfinite(loss)
        if bool(finite):
            self._nonfinite_streak = 0
        else:
            self._nonfinite_streak = getattr(self, "_nonfinite_streak", 0) + 1
            if self._nonfinite_streak < 50:
                loss = torch.where(finite, loss, torch.zeros_like(loss))
                logs = {k: torch.nan_to_num(torch.as_tensor(v, dtype=torch.float32), nan=0.0, posinf=0.0, neginf=0.0)
                        for k, v in logs.items()}
        return loss, logs

    def end_epoch(self, epoch):
        if self.s0.requires_grad and self.s0.grad is not None and float(self.s0.grad.abs().mean()) < 1:
            self.s0.requires_grad_(False)
            self.s1.requires_grad_(False)

# --- block: model ---
WIDTH = 256
N_STAGES = 5
IN_LEN = 2114


def _bottleneck_len(n=IN_LEN, stages=N_STAGES):
    for _ in range(stages):
        n = (n + 1) // 2
    return n


N_BOT = _bottleneck_len()


class CheriBlock(nn.Module):
    """Cherimoya's Cheri block (cherimoya/cheri.py at 8e4283f, pure PyTorch): a 3-tap dilated depthwise conv, a per-example
    layer norm over the whole (length, channel) plane, then an MLP (C -> 2C -> C, tanh GELU) added back with scale 0.15."""

    def __init__(self, channels, dilation=1, expansion=2, residual_scale=0.15, eps=1e-3):
        super().__init__()
        self.dilation, self.residual_scale, self.eps = dilation, residual_scale, eps
        self.conv_weight = nn.Parameter(torch.empty(3, channels))
        self.linear1 = nn.Linear(channels, expansion * channels, bias=False)
        self.linear2 = nn.Linear(expansion * channels, channels, bias=False)
        self.activation = nn.GELU(approximate="tanh")
        for w in (self.conv_weight, self.linear1.weight, self.linear2.weight):
            nn.init.trunc_normal_(w, std=0.02)

    def forward(self, x):                      # x: (B, C, L)
        c = x.shape[1]
        y = F.conv1d(x, self.conv_weight.t().unsqueeze(1).to(x.dtype), padding=self.dilation, dilation=self.dilation, groups=c)
        flat = y.reshape(y.shape[0], -1).float()
        y = ((flat - flat.mean(1, keepdim=True)) * (flat.var(1, keepdim=True, unbiased=False) + self.eps).rsqrt())
        y = y.reshape(x.shape).to(x.dtype).transpose(1, 2)
        y = self.linear2(self.activation(self.linear1(y))).transpose(1, 2)
        return x + y * self.residual_scale


def group_norm(channels, groups=8):
    while channels % groups:
        groups -= 1
    return nn.GroupNorm(groups, channels)


class StandardizedConv1d(nn.Conv1d):
    """CAPYBARA's weight-standardised 'same' convolution."""

    def __init__(self, cin, cout, k, dilation=1):
        super().__init__(cin, cout, k, padding=0, dilation=dilation, bias=True)
        self.scale = nn.Parameter(torch.ones(cout, 1, 1))

    def forward(self, x):
        w = self.weight
        var = w.var(dim=(1, 2), unbiased=False, keepdim=True)
        fan_in = self.in_channels * self.kernel_size[0]
        w = (w - w.mean(dim=(1, 2), keepdim=True)) * torch.rsqrt(torch.clamp(var * fan_in, min=1e-4)) * self.scale
        total = self.dilation[0] * (self.kernel_size[0] - 1)
        x = F.pad(x, (total // 2, total - total // 2))
        return F.conv1d(x, w.to(x.dtype), self.bias.to(x.dtype), dilation=self.dilation)


class ConvBlock(nn.Module):
    """CAPYBARA pre-activation conv block: norm -> GELU -> dropout -> conv."""

    def __init__(self, channels, k, dropout=0.1):
        super().__init__()
        self.norm, self.act, self.drop = group_norm(channels), nn.GELU(), nn.Dropout(dropout)
        self.conv = StandardizedConv1d(channels, channels, k)

    def forward(self, x):
        return self.conv(self.drop(self.act(self.norm(x))))


class LN(nn.Module):
    """LayerNorm over the last dim, statistics in float32 (from C27)."""

    def __init__(self, c, eps=1e-5):
        super().__init__()
        self.weight = nn.Parameter(torch.ones(c))
        self.bias = nn.Parameter(torch.zeros(c))
        self.eps = eps

    def forward(self, x):
        with torch.autocast(device_type=x.device.type, enabled=False):
            y = F.layer_norm(x.float(), (x.shape[-1],), self.weight.float(), self.bias.float(), self.eps)
        return y.to(x.dtype)


class SGUBlock(nn.Module):
    """C27's gMLP block with a spatial gating unit on (B, C, L): u * (W_spatial @ norm(v) + b), W a dense,
    position-specific n x n token-mixing matrix (near-zero init, bias 1, so the gate starts at identity); layer scale."""

    def __init__(self, d=WIDTH, e=2 * WIDTH, n=N_BOT, ls=0.1, dropout=0.05):
        super().__init__()
        self.n = n
        self.norm = LN(d)
        self.fc1 = nn.Linear(d, 2 * e)
        self.gate_norm = LN(e)
        self.spatial = nn.Parameter(torch.empty(n, n))
        nn.init.trunc_normal_(self.spatial, std=1e-3)
        self.spatial_bias = nn.Parameter(torch.ones(n, 1))
        self.fc2 = nn.Linear(e, d)
        self.drop = nn.Dropout(dropout)
        self.gamma = nn.Parameter(torch.full((d,), ls))

    def forward(self, x):
        h = self.norm(x.transpose(1, 2))
        u, v = F.gelu(self.fc1(h), approximate='tanh').chunk(2, dim=-1)
        v = self.gate_norm(v)
        v = torch.matmul(self.spatial.to(v.dtype), v) + self.spatial_bias.to(v.dtype)
        h = self.fc2(self.drop(u * v))
        return x + (self.gamma.to(h.dtype) * h).transpose(1, 2)


class HybridSGUUnit(nn.Module):
    """CAPYBARA HybridAttentionUnit with its self-attention + MLP replaced by C27's gMLP spatial gating block:
    a residual pair of conv blocks, then one SGU block."""

    def __init__(self, channels, k=5, dropout=0.1):
        super().__init__()
        self.conv1, self.conv2 = ConvBlock(channels, k, dropout), ConvBlock(channels, k, dropout)
        self.sgu = SGUBlock(channels)

    def forward(self, x):
        x = x + self.conv2(self.conv1(x))
        return self.sgu(x)


class Encoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES):
        super().__init__()
        self.stem = nn.Conv1d(4, width, 21, padding=10)
        nn.init.trunc_normal_(self.stem.weight, std=0.02)
        nn.init.zeros_(self.stem.bias)
        self.blocks = nn.ModuleList([CheriBlock(width) for _ in range(n_stages)])

    def forward(self, x):
        x = F.gelu(self.stem(x), approximate="tanh")
        skips = []
        for block in self.blocks:
            x = block(x)
            skips.append(x)
            x = F.avg_pool1d(x, 2, ceil_mode=True)
        return x, skips


class Bottleneck(nn.Module):
    def __init__(self, width=WIDTH, depth=3):
        super().__init__()
        self.cheri = CheriBlock(width)
        self.units = nn.Sequential(*[HybridSGUUnit(width) for _ in range(depth)])

    def forward(self, x):
        return self.units(self.cheri(x))


class YCountHead(nn.Module):
    """CAPYBARA YCountHead: conv [128, 64] (kernel 5, GroupNorm, GELU, dropout, max-pool 2), adaptive average pool to 4
    bins, MLP [64] with LayerNorm, then one output: ln(total counts + 1)."""

    def __init__(self, width=WIDTH, convs=(128, 64), mlp=(64,), k=5, bins=4, dropout=0.1):
        super().__init__()
        layers, c = [], width
        for h in convs:
            layers += [nn.Conv1d(c, h, k, padding=k // 2, bias=False), group_norm(h), nn.GELU(), nn.Dropout(dropout),
                       nn.MaxPool1d(2, ceil_mode=True)]
            c = h
        self.convs, self.bins = nn.Sequential(*layers), bins
        layers, d = [], c * bins
        for h in mlp:
            layers += [nn.Linear(d, h), nn.LayerNorm(h), nn.GELU(), nn.Dropout(dropout)]
            d = h
        self.mlp = nn.Sequential(*layers, nn.Linear(d, 1))

    def forward(self, z):
        return self.mlp(F.adaptive_avg_pool1d(self.convs(z), self.bins).flatten(1))


class GatedSkipFusion(nn.Module):
    """up + 2*sigmoid(W[up; skip])*skip, W a zero-initialised kernel-1 conv, so the gate starts at 1."""

    def __init__(self, width=WIDTH):
        super().__init__()
        self.gate = nn.Conv1d(2 * width, width, 1)
        nn.init.zeros_(self.gate.weight)
        nn.init.zeros_(self.gate.bias)

    def forward(self, up, skip):
        return up + 2 * torch.sigmoid(self.gate(torch.cat([up, skip], 1))) * skip


class Decoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES, blocks_per_stage=2):
        super().__init__()
        self.fuse = nn.ModuleList([GatedSkipFusion(width) for _ in range(n_stages)])
        self.blocks = nn.ModuleList([nn.Sequential(*[CheriBlock(width) for _ in range(blocks_per_stage)])
                                     for _ in range(n_stages)])

    def forward(self, z, skips):
        x = z
        for fuse, blocks, skip in zip(self.fuse, self.blocks, reversed(skips)):
            x = F.interpolate(x, size=skip.shape[-1], mode="nearest")
            x = blocks(fuse(x, skip))
        return x


class ProfileHead(nn.Module):
    """Cherimoya's profile head: one kernel-75 conv, then the central 1,000 positions."""

    def __init__(self, width=WIDTH, k=75):
        super().__init__()
        self.conv = nn.Conv1d(width, 1, k, padding=k // 2)
        nn.init.trunc_normal_(self.conv.weight, std=0.02)
        nn.init.zeros_(self.conv.bias)

    def forward(self, h):
        start = (h.shape[-1] - OUT_LEN) // 2
        return self.conv(h)[..., start:start + OUT_LEN]


class CAPY(nn.Module):
    def __init__(self):
        super().__init__()
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = YCountHead()
        self.decoder = Decoder()
        self.profile_head = ProfileHead()
        self.progress, self.epoch = 0.0, 0

    def forward(self, x):
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        counts = self.count_head(z)
        profile = self.profile_head(self.decoder(z, skips))
        return {"profile": profile, "counts": counts}


def build_model():
    return CAPY()

